import { gsap } from 'gsap';
import { MeshStandardNodeMaterial } from 'three/webgpu';
import { uv, vec3, mix, smoothstep, time, uniform } from 'three/tsl';

export default function createNode(config, ctx) {
  const { Group, Mesh, Object3D } = ctx.THREE;

  const root = new Group();
  root.position.set(0, -0.2, 0);
  root.userData.cleanup = () => {
    gsap.killTweensOf(root.position);
    gsap.killTweensOf(root.rotation);
    gsap.killTweensOf(root.scale);

    if (root.userData.primitiveCleanups) {
      root.userData.primitiveCleanups.forEach(fn => fn());
    }

    root.traverse(child => {
      if (child.geometry) child.geometry.dispose();
      if (child.material) {
        if (Array.isArray(child.material)) {
          child.material.forEach(m => m.dispose());
        } else {
          child.material.dispose();
        }
      }
    });
  };

  root.userData.primitiveCleanups = [];
  root.userData.handlers = {};

  // Load the GLB mesh
  ctx.glbLoader.loadGLB(config.meshUrl).then((gltf) => {
    const mesh = gltf.scene;

    // Clone materials and enhance with PBR + emissive accent
    mesh.traverse((child) => {
      if (child.isMesh && child.material) {
        const originalMat = child.material;

        // Create enhanced material with machined-metal aesthetic
        const newMat = new MeshStandardNodeMaterial();

        // Base PBR: brushed metal with restrained clearcoat
        newMat.metalness = 0.48;
        newMat.roughness = 0.55;
        newMat.clearcoat = 0.2;
        newMat.clearcoatRoughness = 0.3;

        // Preserve existing color if present
        if (originalMat.color) {
          newMat.color.copy(originalMat.color);
        } else {
          newMat.color.setHex(0x16161d); // ink fallback
        }

        // Add subtle emissive accent (red signal, low intensity to avoid blow-out)
        newMat.emissive.setHex(0xff2a38);
        newMat.emissiveIntensity = 0.15;

        // Transfer map if exists
        if (originalMat.map) {
          newMat.map = originalMat.map;
        }

        child.material = newMat;
      }
    });

    root.add(mesh);

    // Apply cinematic primitives
    // 1. Parallax scroll
    const parallaxResult = ctx.primitives['parallax-scroll'](root, { 
      intensity: 0.4 
    });
    if (parallaxResult && parallaxResult.cleanup) {
      root.userData.primitiveCleanups.push(parallaxResult.cleanup);
    }

    // 2. Magnetic cursor on hover
    const magneticResult = ctx.primitives['magnetic-cursor'](root, { 
      radius: 1.2,
      strength: 0.35
    });
    if (magneticResult && magneticResult.cleanup) {
      root.userData.primitiveCleanups.push(magneticResult.cleanup);
    }
  });

  // Hover interaction: rise-in entrance
  root.userData.handlers.onHover = (isHovering) => {
    if (isHovering) {
      gsap.to(root.position, {
        y: -0.2 + 0.15,
        duration: 0.7,
        ease: 'power3.out',
        overwrite: 'auto'
      });
    } else {
      gsap.to(root.position, {
        y: -0.2,
        duration: 0.7,
        ease: 'power3.out',
        overwrite: 'auto'
      });
    }
  };

  // Click interaction: emit event
  root.userData.handlers.onClick = () => {
    ctx.emit('navigate', { to: 'hub-collection' });
  };

  return root;
}
